mapper.update:
update hse_hazardous_waste_outsourcing
set del_flag = 1
where sid = #{sid}

mapper.select:
select sid, app_id, remark, create_by, create_time, update_by, update_time, del_flag, tenant_id, tenant_name, outsourcing_type_code, outsourcing_type_name, waste_base_id, source, delivery_time, disposal_code, disposal_volume, packaging_and_type_code, packaging_and_type_name, number_of_packages, disposal_method_code, disposal_method_name, receiving_unit_type_id, receiving_unit_type_name, unit_id, unit_name, export_document_number, license_code, generation_outbound_Ids, generation_outbound_batch_encoding, year_tag, serial_number from hse_hazardous_waste_outsourcing where sid in
#{item}
and del_flag=0

select
sid,
app_id,
remark,
create_by,
create_time,
update_by,
update_time,
del_flag,
tenant_id,
tenant_name,
outsourcing_type_code,
outsourcing_type_name,
waste_base_id,
source,
delivery_time,
disposal_code,
disposal_volume,
packaging_and_type_code,
packaging_and_type_name,
number_of_packages,
disposal_method_code,
disposal_method_name,
receiving_unit_type_id,
receiving_unit_type_name,
unit_id,
unit_name,
export_document_number,
license_code,
generation_outbound_Ids,
generation_outbound_batch_encoding,
year_tag,
serial_number
from hse_hazardous_waste_outsourcing
where app_id = #{appId} and del_flag=0

    and sid = #{sid}


    and app_id = #{appId}


    and remark = #{remark}


    and create_by = #{createBy}


    and create_time = #{createTime}


    and update_by = #{updateBy}


    and update_time = #{updateTime}


    and del_flag = #{delFlag}


    and tenant_id = #{tenantId}


    and tenant_name = #{tenantName}


    and outsourcing_type_code = #{outsourcingTypeCode}


    and outsourcing_type_name = #{outsourcingTypeName}


    and waste_base_id = #{wasteBaseId}


    and source = #{source}


    and delivery_time = #{deliveryTime}


    and disposal_code = #{disposalCode}


    and disposal_volume = #{disposalVolume}


    and packaging_and_type_code = #{packagingAndTypeCode}


    and packaging_and_type_name = #{packagingAndTypeName}


    and number_of_packages = #{numberOfPackages}


    and disposal_method_code = #{disposalMethodCode}


    and disposal_method_name = #{disposalMethodName}


    and receiving_unit_type_id = #{receivingUnitTypeId}


    and receiving_unit_type_name = #{receivingUnitTypeName}


    and unit_id = #{unitId}


    and unit_name = #{unitName}


    and export_document_number = #{exportDocumentNumber}


    and license_code = #{licenseCode}


    and generation_outbound_Ids = #{generationOutboundIds}


    and generation_outbound_batch_encoding = #{generationOutboundBatchEncoding}


    and year_tag = #{yearTag}


    and serial_number = #{serialNumber}

select o.sid, o.app_id, o.remark, o.create_by, o.create_time, o.update_by, o.update_time, o.del_flag, o.tenant_id, o.tenant_name, o.outsourcing_type_code, o.outsourcing_type_name, o.waste_base_id, o.source, o.delivery_time, o.disposal_code, o.disposal_volume, o.packaging_and_type_code, o.packaging_and_type_name, o.number_of_packages, o.disposal_method_code, o.disposal_method_name, o.receiving_unit_type_id, o.receiving_unit_type_name, o.unit_id, o.unit_name, o.export_document_number, o.license_code, o.generation_outbound_Ids, o.generation_outbound_batch_encoding, o.year_tag, o.serial_number from hse_hazardous_waste_outsourcing o
left join hse_hazardous_waste_base base on base.sid = o.waste_base_id left join hse_hazardous_waste_directory directory on base.directory_id = directory.sid
and o.sid in
#{item}
and ( o.disposal_code like concat('%',#{keyWord},'%') or base.waste_name like concat('%',#{keyWord},'%') or directory.waste_code like concat('%',#{keyWord},'%') )
and o.outsourcing_type_code = #{outsourcingTypeCode}
and o.waste_base_id = #{wasteBaseId}
and o.disposal_code = #{disposalCode}
and o.source = #{source}
and o.packaging_and_type_code = #{packagingAndTypeCode}
and o.disposal_method_code = #{disposalMethodCode}
and o.receiving_unit_type_id = #{receivingUnitTypeId}
and o.unit_id = #{unitId}
and o.unit_name = #{unitName}
and o.export_document_number = #{exportDocumentNumber}
and o.license_code = #{licenseCode}
and o.year_tag = #{yearTag}
and o.serial_number = #{serialNumber}
and o.delivery_time >= #{searchStartDate} and delivery_time <= #{searchEndDate}
and o.del_flag = 0 and o.app_id = #{appId}
